return ['x-generator'=>'GlotPress/4.0.3','translation-revision-date'=>'2025-01-27 23:38:54+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - Modern Image Formats - Stable (latest release)','language'=>'de','messages'=>['This setting requires fallback image output to be enabled.'=>'Diese Einstellung erfordert die Aktivierung der Fallback-Bildausgabe.','Also generate fallback images in the original upload format'=>'Fallback-Bilder auch im ursprünglichen Upload-Format erzeugen','Output fallback images'=>'Fallback-Bilder ausgeben','Picture elements will only be used when fallback images are available. So this will only apply to  images you have uploaded while the "Also generate fallback images" setting was enabled.'=>'Picture-Elemente werden nur verwendet, wenn Fallback-Bilder verfügbar sind. Das gilt also nur für Bilder, die du hochgeladen hast, während die Einstellung „Fallback-Bilder erzeugen“ aktiviert war.','settings page section nameModern Image Formats'=>'Modern Image Formats','The picture element serves a modern image format with a fallback to the original upload format. Warning: Make sure you test your theme and plugins for compatibility. In particular, CSS selectors will not match images when using the child combinator (e.g. figure > img).'=>'Das Picture-Element liefert ein modernes Bildformat mit einem Fallback zum ursprünglichen Upload-Format. Warnung: Teste unbedingt dein Theme und deine Plugins auf Kompatibilität. Insbesondere CSS-Selektoren funktionieren nicht, wenn der Kind-Kombinator verwendet wird (z. B. figure > img).','(experimental)'=>'(experimentell)','Use <picture> Element'=>'Das Element <picture> verwenden','Enabling fallback image output can improve compatibility, but will increase the filesystem storage use of your images.'=>'Die Aktivierung der Fallback-Bildausgabe kann die Kompatibilität verbessern, aber den Speicherplatzbedarf deiner Bilder erhöhen.','WebP support can only be enabled by your hosting provider, so contact them for more information.'=>'WebP-Unterstützung kann nur von deinem Hosting-Anbieter aktiviert werden. Wende dich für weitere Informationen an diesen.','WebP support is not available.'=>'WebP-Unterstützung ist nicht verfügbar.','AVIF support can only be enabled by your hosting provider, so contact them for more information.'=>'AVIF-Unterstützung kann nur von deinem Hosting-Anbieter aktiviert werden. Wende dich für weitere Informationen an diesen.','AVIF support is not available.'=>'AVIF-Unterstützung ist nicht verfügbar.','Select the format to use when generating new images from uploaded images.'=>'Wähle das Format, das beim Erstellen neuer Bilder aus hochgeladenen Bildern verwendet werden soll.','Generate images in this format'=>'Bilder in diesem Format erzeugen','AVIF'=>'AVIF','WebP'=>'WebP','WebP or AVIF support can only be enabled by your hosting provider, so contact them for more information.'=>'WebP- oder AVIF-Unterstützung kann nur von deinem Hosting-Anbieter aktiviert werden. Wende dich für weitere Informationen an diesen.','Modern image support is not available.'=>'Unterstützung für moderne Bildformate ist nicht verfügbar.','Picture element'=>'Bildelement','Image output format'=>'Format für die Bildausgabe','Settings'=>'Einstellungen','Converts images to more modern formats such as WebP or AVIF during upload.'=>'Konvertiert Bilder während des Uploads in modernere Formate wie WebP oder AVIF.','Modern Image Formats'=>'Modern Image Formats','The image does not have a valid metadata.'=>'Das Bild hat keine gültigen Metadaten.','The file key is not present on the image data'=>'Der Dateischlüssel ist in den Bilddaten nicht vorhanden','At least one of the dimensions must be a positive number.'=>'Mindestens eine der Dimensionen muss eine positive Zahl sein.','The original image file does not exists, subsizes are created out of the original image.'=>'Die ursprüngliche Bilddatei ist nicht vorhanden. Untergrößen werden aus dem Originalbild erstellt.','The provided mime type is not supported.'=>'Der bereitgestellte Mime-Typ wird nicht unterstützt.','The provided mime type is not allowed.'=>'Der bereitgestellte Mime-Typ ist nicht zulässig.','https://make.wordpress.org/performance/'=>'https://make.wordpress.org/performance/','WordPress Performance Team'=>'Das WordPress-Performance-Team','https://github.com/WordPress/performance/tree/trunk/plugins/webp-uploads'=>'https://github.com/WordPress/performance/tree/trunk/plugins/webp-uploads']];